#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 vector<vector<int>> substringXorQueries(string s,vector<vector<int>>& queries){
  unordered_map<int,pair<int,int>> pos;int n=s.size();
  for(int i=0;i<n;++i){
   if(s[i]=='0'){if(!pos.count(0))pos[0]={i,i};continue;}
   int value=0;
   for(int j=i;j<n&&j<i+30;++j){value=(value<<1)|(s[j]-'0');if(!pos.count(value))pos[value]={i,j};}
  }
  vector<vector<int>> ans;for(auto &q:queries){int x=q[0]^q[1];
   if(pos.count(x))ans.push_back({pos[x].first,pos[x].second});else ans.push_back({-1,-1});
  }return ans;
 }
};
